{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table hox_db.maplemonk.HOX_yfl_sevenchef_SAAS_cost as with B2C_base as ( select marketplace, reference_code, order_type, quantity, Suborder_No, Report_date from hox_db.maplemonk.HOX_YFL_Easyecom_Tax_Fact_Items where lower(ORDER_TYPE) = \'b2c\' and lower(REPORT_TYPE) = \'easyecom yfl sale\' ), B2B_base as ( select marketplace, reference_code, order_type, quantity, Suborder_No, Report_date from hox_db.maplemonk.HOX_YFL_Easyecom_Tax_Fact_Items where lower(ORDER_TYPE) in (\'b2b\', \'stn\') and lower(REPORT_TYPE) = \'easyecom yfl sale\' ), Other_B2C_base as ( select o.reference_code, o.marketplace, Report_date, case when (tot_quantity / 3) < 1 then 4 else (ceil(tot_quantity / 3)*4) end as Easyecom_cost from ( select reference_code, marketplace, Report_date, sum(quantity)as tot_quantity from B2C_base where lower(marketplace) not like \'%flipkart%\' group by 1,2,3 )as o ), Flipkart_B2C_base as ( select o.reference_code, o.marketplace, o.Report_date, sum(case when (tot_quantity / 3) < 1 then 4 else (ceil(tot_quantity / 3)*4) end) as Easyecom_cost from ( select reference_code, Suborder_No, marketplace, Report_date, sum(quantity)as tot_quantity from B2C_base where lower(marketplace) like \'%flipkart%\' group by 1,2,3,4 )as o group by 1,2,3 ), B2B_easyecom_base as ( select o.reference_code, o.marketplace, o.Report_date, case when (tot_quantity / 20) < 1 then 4 else (ceil(tot_quantity / 20)*4) end as Easyecom_cost from ( select reference_code, marketplace, Report_date, sum(quantity)as tot_quantity from B2B_base group by 1,2,3 )as o ), Interakt_base as ( select marketplace, reference_code, report_date, sum(case when report_date >= date(\'2023-01-01\') then 2.5 end) as Interakt_cost from ( select distinct marketplace, reference_code, report_date from hox_db.maplemonk.HOX_YFL_Easyecom_Tax_Fact_Items where lower(marketplace) like \'%shopify%\' and lower(REPORT_TYPE) = \'easyecom yfl sale\' )as o group by 1,2,3 ), ClickPost_base as ( select marketplace, reference_code, report_date, round(div0(5000, count(1) over (partition by month_Date order by 1)),2) as Clickpost_cost from ( select distinct marketplace, reference_code, report_date, date(date_trunc(\'month\', report_date)) as month_Date from hox_db.maplemonk.HOX_YFL_Easyecom_Tax_Fact_Items where lower(marketplace) like \'%shopify%\' and lower(REPORT_TYPE) = \'easyecom yfl sale\' and lower(order_status) not like \'%cancel%\' )as o ), final_base_EE as ( select distinct o.*, date(date_trunc(\'month\', a.report_date)) as month_Date from ( select * from Other_B2C_base union select * from Flipkart_B2C_base union select * from B2B_easyecom_base )as o inner join ( select distinct reference_code, report_date from hox_db.maplemonk.HOX_YFL_Easyecom_Tax_Fact_Items where lower(REPORT_TYPE) = \'easyecom yfl sale\' ) a on o.reference_code = a.reference_code ), EE_base_data as ( select reference_code, marketplace, report_date, sum(EE_cost)as Easyecom_cost from ( select a.reference_code, a.marketplace, a.report_date, a.month_Date, round(div0(o.Easyecom_cost, count(1) over (partition by a.month_Date order by 1)),2) as EE_cost from final_base_EE a left join ( select distinct o.month_Date, case when EE_cost <= 25000 then 25000 else EE_cost end as Easyecom_cost from ( select month_Date , sum(Easyecom_cost)as EE_cost from final_base_EE group by 1 order by 1 )as o )as o on a.month_Date = o.month_Date )as o group by 1,2,3 ) select distinct o.*, a.Interakt_cost, b.Clickpost_cost from EE_base_data o left join Interakt_base a on o.REFERENCE_CODE = a.REFERENCE_CODE and o.report_date = a.report_date left join ClickPost_base b on o.REFERENCE_CODE = b.REFERENCE_CODE and o.report_date = b.report_date",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from HOX_DB.information_schema.databases
            ),
            
            final as (
